/**
 * The SQL of drizzle/0040 (WA-TEMPLATES-1023): the whatsapp_generations table and one WhatsApp
 * template dynasty per Cold WhatsApp pipe, v1 (deprecated "Upgraded") then v2 (head, active).
 * Generated by scripts/generate-whatsapp-seed.ts; pinned by tests/unit/whatsapp-templates.test.ts.
 */
import {
  WHATSAPP_DYNASTY_SEEDS,
  WHATSAPP_FEATURE_SLUG,
  WHATSAPP_TEMPLATE_V1,
  WHATSAPP_TEMPLATE_V2,
  WHATSAPP_TEMPLATE_VARIABLES,
} from "./whatsapp-templates.js";
import { extractTemplateVariableNames } from "./template-vars.js";

const BREAK = "\n--> statement-breakpoint\n";

function lit(s: string): string {
  if (s.includes("$wa$")) throw new Error("seed text contains the dollar-quote tag");
  return `$wa$${s}$wa$`;
}

/** The declared variables of a text: exactly its tokens, with their catalogue descriptions. */
export function variablesOf(text: string): Array<{ name: string; description: string }> {
  return extractTemplateVariableNames(text).map((name) => {
    const v = WHATSAPP_TEMPLATE_VARIABLES.find((x) => x.name === name);
    if (!v) throw new Error(`token {{${name}}} has no catalogue entry`);
    return v;
  });
}

export function buildWhatsAppSeedSql(): string {
  const stmts: string[] = [
    `-- WhatsApp templates (WA-TEMPLATES-1023, owner 2026-10-23). Generated by scripts/generate-whatsapp-seed.ts\n-- from src/lib/whatsapp-templates.ts: do not edit by hand.\nCREATE TABLE IF NOT EXISTS "whatsapp_generations" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "run_id" text NOT NULL,
  "brand_ids" text[] NOT NULL,
  "campaign_id" text NOT NULL,
  "lead_id" text,
  "workflow_slug" text,
  "feature_slug" text,
  "prompt_type" text NOT NULL,
  "model" text NOT NULL,
  "decision" text NOT NULL,
  "bubbles" jsonb NOT NULL,
  "reason" text,
  "next_follow_up_at" text,
  "next_follow_up_why" text,
  "tokens_input" integer,
  "tokens_output" integer,
  "system_prompt_raw" text,
  "context_raw" text,
  "variables_raw" jsonb,
  "response_raw" jsonb,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
)`,
    `CREATE INDEX IF NOT EXISTS "idx_wagen_feature_created" ON "whatsapp_generations" ("feature_slug", "created_at", "id")`,
    `CREATE INDEX IF NOT EXISTS "idx_wagen_prompt_type_created" ON "whatsapp_generations" ("prompt_type", "created_at")`,
    `CREATE INDEX IF NOT EXISTS "idx_wagen_campaign_lead" ON "whatsapp_generations" ("campaign_id", "lead_id")`,
  ];
  for (const d of WHATSAPP_DYNASTY_SEEDS) {
    const [v1, v2] = d.types;
    stmts.push(
      `INSERT INTO "prompts" ("org_id", "type", "prompt", "variables", "status", "status_changed_at", "status_reason", "status_changed_by") VALUES ` +
        `(NULL, ${lit(v1)}, ${lit(WHATSAPP_TEMPLATE_V1)}, ${lit(JSON.stringify(variablesOf(WHATSAPP_TEMPLATE_V1)))}::jsonb, 'deprecated', now(), 'Upgraded', 'template-dynasty-upgrade'), ` +
        `(NULL, ${lit(v2)}, ${lit(WHATSAPP_TEMPLATE_V2)}, ${lit(JSON.stringify(variablesOf(WHATSAPP_TEMPLATE_V2)))}::jsonb, 'active', NULL, NULL, NULL)`,
      `INSERT INTO "template_dynasties" ("slug", "name", "description", "signature", "identity", "feature_slug", "leg_key") VALUES ` +
        `(${lit(d.slug)}, ${lit(d.name)}, ${lit(d.description)}, ${lit(d.signature)}, 'named', ${lit(WHATSAPP_FEATURE_SLUG)}, ${lit(d.legKey)})`,
      `INSERT INTO "template_dynasty_versions" ("dynasty_slug", "prompt_type", "position") VALUES (${lit(d.slug)}, ${lit(v1)}, 1), (${lit(d.slug)}, ${lit(v2)}, 2)`,
    );
  }
  return stmts.join(`;${BREAK}`) + ";\n";
}
